#[test]
fn test_button_hover_states_defined() {
    use iced::widget::button;
    let theme = nodoka_theme();

    // Verify all button styles define hover states
    let primary_hover = button_styles::primary(&theme, button::Status::Hovered);
    let secondary_hover = button_styles::secondary(&theme, button::Status::Hovered);
    let danger_hover = button_styles::danger(&theme, button::Status::Hovered);

    // Hover states should differ from active states
    let primary_active = button_styles::primary(&theme, button::Status::Active);
    assert_ne!(
        primary_hover.background, primary_active.background,
        "Primary button hover state should differ from active state"
    );

    // Secondary button hover should have different background
    let secondary_active = button_styles::secondary(&theme, button::Status::Active);
    assert_ne!(
        secondary_hover.background, secondary_active.background,
        "Secondary button hover state should differ from active state"
    );

    // Danger button hover should have different background
    let danger_active = button_styles::danger(&theme, button::Status::Active);
    assert_ne!(
        danger_hover.background, danger_active.background,
        "Danger button hover state should differ from active state"
    );
}

